-- ============================================================
-- 407 体检套餐扩容：补齐体检中心产品线（6 个 → 16 个有效套餐）
-- 日期：2026-11-27
-- 背景：sys_checkup_package 仅有基础（男/女）、入职、中老年（男/女）、VIP 6 个套餐，
--       体检登记下拉可选项过少，前台无法按人群/用途开单。
-- 内容：新增 10 个套餐（PK007~PK016）+ 113 条明细，覆盖学生、公务员录用、驾驶员、
--       孕前优生（女）、心脑血管专项、糖尿病代谢、女性两癌、肿瘤早筛（男/女）、老年综合评估。
-- 口径：
--   1) 明细金额合计 = 套餐价格（逐单核对，见文件末校验 SQL），登记按套餐价收费。
--   2) gender_limit 0-不限 1-男 2-女；item_type 1-检验 2-检查 3-一般。
--   3) 幂等：按主键 INSERT ... ON DUPLICATE KEY UPDATE id = id，重复执行不产生重复套餐。
-- 回滚：见 407-回滚.sql
-- ============================================================
SET NAMES utf8mb4;
START TRANSACTION;

-- 套餐主表（10 行）
ON DUPLICATE KEY UPDATE `id` = `id`;

-- 套餐明细（113 行）
ON DUPLICATE KEY UPDATE `id` = `id`;

COMMIT;

-- 校验：每个有效套餐明细合计应等于套餐价格（应返回 0 行）
