  (2350000000000000601, '学生健康体检套餐', 'PK007', 0, '256.00', '覆盖生长发育、视力、结核筛查等在校学生常见项目，适合小学至高中入学与年度体检', 1, 'admin', '2026-11-27 00:00:00', 'admin', '2026-11-27 00:00:00', 0, NULL, 1, 1),
  (2350000000000000602, '公务员录用体检套餐', 'PK008', 0, '641.00', '按公务员录用体检通用标准配置，含传染病筛查与腹部彩超，出具体检结论', 1, 'admin', '2026-11-27 00:00:00', 'admin', '2026-11-27 00:00:00', 0, NULL, 1, 1),
  (2350000000000000603, '驾驶员体检套餐', 'PK009', 0, '66.00', '按机动车驾驶人体检要求配置，含视力、色觉、听力与血压，当场出具身体条件证明', 1, 'admin', '2026-11-27 00:00:00', 'admin', '2026-11-27 00:00:00', 0, NULL, 1, 1),
  (2350000000000000604, '孕前优生检查套餐（女）', 'PK010', 2, '758.00', '备孕女性优生优育筛查：TORCH、甲功、血型与妇科超声，降低出生缺陷风险', 1, 'admin', '2026-11-27 00:00:00', 'admin', '2026-11-27 00:00:00', 0, NULL, 1, 1),
  (2350000000000000605, '心脑血管专项筛查套餐', 'PK011', 0, '968.00', '面向高血压、高血脂及卒中家族史人群：颈动脉与心脏超声、TCD、头颅CT 联合评估', 1, 'admin', '2026-11-27 00:00:00', 'admin', '2026-11-27 00:00:00', 0, NULL, 1, 1),
  (2350000000000000606, '糖尿病及代谢筛查套餐', 'PK012', 0, '543.00', '含糖化血红蛋白、胰岛素释放与尿微量白蛋白，评估血糖控制与早期肾、眼底、下肢血管并发症', 1, 'admin', '2026-11-27 00:00:00', 'admin', '2026-11-27 00:00:00', 0, NULL, 1, 1),
