  (2350000000000000608, '肿瘤早期筛查套餐（男）', 'PK014', 1, '1296.00', '男性常见肿瘤联合筛查：肿瘤标志物全套、胸部CT、腹部及甲状腺超声、幽门螺杆菌', 1, 'admin', '2026-11-27 00:00:00', 'admin', '2026-11-27 00:00:00', 0, NULL, 1, 1),
  (2350000000000000609, '肿瘤早期筛查套餐（女）', 'PK015', 2, '1496.00', '女性常见肿瘤联合筛查：肿瘤标志物全套、胸部CT、乳腺与子宫附件超声、幽门螺杆菌', 1, 'admin', '2026-11-27 00:00:00', 'admin', '2026-11-27 00:00:00', 0, NULL, 1, 1),
